import {createCircuitLayout} from './circuit-layout.mjs?v=20261024-tour1';
const routes=new Map();
export function dashboardNavigation(race,rect){const layout=createCircuitLayout(race.difficulty,race.trackLength,race.circuit),frame=layout.frame(race.distance),offset=race.x*race.settings.roadHalf,position=[frame.p[0]+frame.r[0]*offset,frame.p[1],frame.p[2]+frame.r[2]*offset],scale=Math.min(rect.w,rect.h)/140;const project=p=>{const dx=p[0]-position[0],dz=p[2]-position[2];return [rect.x+rect.w*.57+(dx*frame.r[0]+dz*frame.r[2])*scale,rect.y+rect.h*.73-(dx*frame.t[0]+dz*frame.t[2])*scale];};return {layout,position,project};}
export function steeringRotation(steering){return Math.max(-1,Math.min(1,steering))*.9;}
export function drawCircuitNavigation(ctx,race,rect,radioOn=false){const nav=dashboardNavigation(race,rect),key=race.difficulty+':'+race.trackLength+':'+(race.circuit||'club');let points=routes.get(key);if(!points){points=Array.from({length:513},(_,i)=>nav.layout.position(nav.layout.length*i/512));routes.set(key,points);}ctx.save();ctx.beginPath();ctx.rect(rect.x,rect.y,rect.w,rect.h);ctx.clip();ctx.fillStyle='#152324';ctx.fillRect(rect.x,rect.y,rect.w,rect.h);
 ctx.strokeStyle='#26383a';ctx.lineWidth=.6;for(let i=0;i<rect.w;i+=15){ctx.beginPath();ctx.moveTo(rect.x+i,rect.y);ctx.lineTo(rect.x+i,rect.y+rect.h);ctx.stroke();}for(let i=0;i<rect.h;i+=15){ctx.beginPath();ctx.moveTo(rect.x,rect.y+i);ctx.lineTo(rect.x+rect.w,rect.y+i);ctx.stroke();}
 for(const [color,width]of [['#081214',8],['#84999a',5],['#4ed4e3',2.2]]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.beginPath();for(const [i,p]of points.entries()){const [x,y]=nav.project(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}
 const [mx,my]=nav.project(nav.layout.position(2.5));ctx.fillStyle='#f8e9ba';ctx.fillRect(mx-3,my-2,6,4);
 for(const car of race.rivals){const f=nav.layout.frame(car.distance),[x,y]=nav.project([f.p[0]+f.r[0]*car.x*race.settings.roadHalf,f.p[1],f.p[2]+f.r[2]*car.x*race.settings.roadHalf]);ctx.fillStyle=car.retired?'#f16c38':car.model==='tesla-model-3'?'#fff':'#77b8ff';ctx.beginPath();ctx.arc(x,y,1.8,0,Math.PI*2);ctx.fill();}
 const [cx,cy]=nav.project(nav.position);ctx.fillStyle='#ffcd4f';ctx.strokeStyle='#111';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(cx,cy-5);ctx.lineTo(cx+4,cy+5);ctx.lineTo(cx,cy+3);ctx.lineTo(cx-4,cy+5);ctx.closePath();ctx.fill();ctx.stroke();ctx.font='bold '+Math.max(5,Math.min(8,rect.h*.12))+'px Arial';ctx.textAlign='right';ctx.fillStyle='#e4f4f0';ctx.fillText('NAV · '+race.settings.name.toUpperCase(),rect.x+rect.w-4,rect.y+9);ctx.fillText(Math.round(race.speed*3.6)+' km/h',rect.x+rect.w-4,rect.y+rect.h-4);ctx.textAlign='left';ctx.fillStyle=radioOn?'#1ed760':'#a3b5b3';ctx.fillText(radioOn?'RADIO ON':'RADIO OFF',rect.x+4,rect.y+rect.h-4);ctx.restore();return nav;}
